begin;
create function public.crm_meta_spend(p_account text,d jsonb,p_dimension text default 'campaign',p_page integer default 1)returns jsonb language plpgsql stable security definer set search_path=''as $$
declare org uuid:=crm_private.ad_report_org();a crm_private.meta_accounts;j crm_private.meta_jobs;analyst boolean;lo date;hi date;compatible boolean;subset boolean;result jsonb;k text;begin
 select role='creative_analyst'into analyst from public.organization_memberships where user_id=auth.uid()and organization_id=org and active;
 if p_account is null or p_account!~'^act_[0-9]+$'or p_dimension is null or p_dimension not in('campaign','ad','creative')or p_page is null or p_page<1 or p_page>100000 or d is null or jsonb_typeof(d)<>'object'or exists(select 1 from jsonb_object_keys(d)x where x not in('from','to','brand','product','source'))or coalesce(d->>'from','')!~'^\d{4}-\d{2}-\d{2}$'or coalesce(d->>'to','')!~'^\d{4}-\d{2}-\d{2}$'then raise exception 'Invalid spend report'using errcode='22023';end if;
 lo=(d->>'from')::date;hi=(d->>'to')::date;if lo<'2000-01-01'or hi>'2100-12-31'or hi<lo or hi-lo>89 then raise exception 'Choose 1-90 inclusive days'using errcode='22023';end if;
 foreach k in array array['brand','product','source']loop if d?k and(jsonb_typeof(d->k)is distinct from 'string'or d->>k not in('','unknown')and d->>k!~'^[a-f0-9-]{36}$')then raise exception 'Invalid subset filter'using errcode='22023';end if;end loop;
 subset=coalesce(d->>'brand','')<>''or coalesce(d->>'product','')<>''or coalesce(d->>'source','')<>'';
 select * into a from crm_private.meta_accounts where organization_id=org and id=p_account;if not found then raise exception 'Account unavailable'using errcode='42501';end if;select * into j from crm_private.meta_jobs where id=a.current_snapshot and organization_id=org and state='completed';compatible=j.id is not null and j.since<=lo and j.until>=hi and a.timezone in('Asia/Kolkata','Asia/Calcutta')and not subset and p_dimension<>'creative';
 with population as materialized(
 select e.external_id ad_id,e.data->>'campaign_id'campaign_id,e.data->>'creative_id'creative_id from crm_private.meta_entities e where e.job_id=j.id and e.kind='ad'
 union all select distinct s.ad_id,s.campaign_id,null from crm_private.meta_daily s where s.job_id=j.id and not exists(select 1 from crm_private.meta_entities e where e.job_id=j.id and e.kind='ad'and e.external_id=s.ad_id)
 ), facts as materialized(
 select p.ad_id,case p_dimension when 'ad'then p.ad_id when 'campaign'then coalesce(p.campaign_id,'unknown')else coalesce(p.creative_id,'unknown')end group_key,s.day,s.spend,s.lead_actions,s.campaign_id is distinct from p.campaign_id and s.day is not null relation_mismatch from population p left join crm_private.meta_daily s on s.job_id=j.id and s.ad_id=p.ad_id and s.day between lo and hi
 ),cohort as materialized(
 select l.id,e.eligibility->p_dimension->>'id'group_key,exists(select 1 from public.confirmation_events c where c.organization_id=org and c.lead_id=l.id and c.confirmed_at<=statement_timestamp())confirmed
 from public.leads l left join crm_private.meta_lead_eligibility e on e.lead_id=l.id and e.organization_id=org left join public.lead_ingestion i on i.lead_id=l.id and i.organization_id=org
 where l.organization_id=org and l.created_at>=lo::timestamp at time zone'Asia/Kolkata'and l.created_at<(hi+1)::timestamp at time zone'Asia/Kolkata'
 and e.eligibility->p_dimension->>'account'=p_account
 and(coalesce(d->>'brand','')=''or coalesce(i.source_snapshot->'configured_attribution'->'brand'->>'id','unknown')=d->>'brand')and(coalesce(d->>'product','')=''or coalesce(i.source_snapshot->'configured_attribution'->'product'->>'id','unknown')=d->>'product')and(coalesce(d->>'source','')=''or coalesce(i.source_id::text,'unknown')=d->>'source')
 ),aggregated as materialized(
 select f.group_key,max(coalesce(e.data->>'name','Unavailable provider name'))name,sum(f.spend)spend,count(f.day)rows_seen,count(distinct f.ad_id)*(hi-lo+1)rows_expected,
 case when count(f.lead_actions)=count(f.day)and count(f.day)>0 then sum(f.lead_actions)else null end meta_leads,bool_or(f.relation_mismatch)relation_mismatch,
 (select count(*)from cohort c where c.group_key=f.group_key)n,(select count(*)from cohort c where c.group_key=f.group_key and c.confirmed)confirmed
 from facts f left join crm_private.meta_entities e on e.job_id=j.id and e.kind=p_dimension and e.external_id=f.group_key group by f.group_key
 ),safe_rows as materialized(
 select group_key,name,spend::text spend,case when analyst then crm_private.ad_private_count(n,meta_leads::bigint)else meta_leads end meta_reported_leads,
 case when analyst then(n/5)*5 else n end crm_attributed_leads,case when analyst then crm_private.ad_private_count(n,confirmed)else confirmed end crm_observed_confirmed,
 case when not analyst and compatible and not relation_mismatch and rows_seen=rows_expected and n>0 then round(spend/n,6)::text else null end crm_cpl,
 case when not analyst and compatible and not relation_mismatch and rows_seen=rows_expected and confirmed>0 then round(spend/confirmed,6)::text else null end crm_cost_per_confirmation,
 case when analyst then 'privacy_protected'when j.id is null then 'no_completed_snapshot'when j.since>lo or j.until<hi then 'outside_published_coverage'when a.timezone not in('Asia/Kolkata','Asia/Calcutta')then 'account_daily_window_not_IST'when subset then 'spend_cannot_partition_to_lead_subset'when p_dimension='creative'then 'current_creative_allocation_not_historical_version_proof'when relation_mismatch then 'provider_relationship_changed'when rows_seen<>rows_expected then 'missing_ad_day_rows_not_assumed_zero'when n=0 then 'zero_CRM_denominator'else 'partial_capture_Step_6B_pending' end cost_note,
 case when rows_seen=0 then 'no_rows_returned_not_verified_zero'when rows_seen<rows_expected then 'missing_ad_day_rows'else 'complete_explicit_ad_day_rows'end data_state
 from aggregated where not analyst or n>=5
 )
 select jsonb_build_object('account',jsonb_build_object('id',a.id,'name',a.name,'currency',a.currency,'timezone',a.timezone),'as_of',statement_timestamp(),'last_success',a.last_success_at,'coverage',case when j.id is null then null else jsonb_build_object('since',j.since,'until',j.until,'snapshot',j.id)end,
 'provisional',hi>=(now()at time zone a.timezone)::date,'capture','Step 6B pending: CRM capture may be incomplete. Calculated CRM costs are partial-capture descriptive ratios, not reliable overall campaign CPL.','grain','ad/account-local-day; no mixed-currency total','attribution_settings',coalesce((select jsonb_agg(distinct data->'attribution_spec')from crm_private.meta_entities where job_id=j.id and kind='adset'),'[]'::jsonb),'meta_action_definition','actions[action_type=lead] only; absent is unavailable, not zero; use_unified_attribution_setting=true; action_report_time=impression','privacy',case when analyst then 'k=5; small/complementary cells withheld, counts rounded; cost ratios unavailable'else 'exact eligible reviewed-mapping denominators'end,
 'mapping_coverage',case when analyst then null else(select jsonb_build_object('recorded_received',count(*),'eligible_to_selected_account',count(*)filter(where e.eligibility->p_dimension->>'account'=p_account),'unknown_or_unmapped',count(*)filter(where e.eligibility->p_dimension->>'account'is null),'other_account',count(*)filter(where e.eligibility->p_dimension->>'account'is not null and e.eligibility->p_dimension->>'account'<>p_account))from public.leads l left join crm_private.meta_lead_eligibility e on e.lead_id=l.id and e.organization_id=org left join public.lead_ingestion i on i.lead_id=l.id and i.organization_id=org where l.organization_id=org and l.created_at>=lo::timestamp at time zone'Asia/Kolkata'and l.created_at<(hi+1)::timestamp at time zone'Asia/Kolkata'and(coalesce(d->>'brand','')=''or coalesce(i.source_snapshot->'configured_attribution'->'brand'->>'id','unknown')=d->>'brand')and(coalesce(d->>'product','')=''or coalesce(i.source_snapshot->'configured_attribution'->'product'->>'id','unknown')=d->>'product')and(coalesce(d->>'source','')=''or coalesce(i.source_id::text,'unknown')=d->>'source'))end,'groups_total',(select count(*)from safe_rows),'rows',coalesce((select jsonb_agg(to_jsonb(x)order by x.group_key)from(select * from safe_rows order by group_key limit 20 offset(p_page-1)*20)x),'[]'::jsonb))into result;return result;
end$$;
create function public.crm_meta_report_accounts()returns jsonb language plpgsql stable security definer set search_path=''as $$declare org uuid:=crm_private.ad_report_org();begin return coalesce((select jsonb_agg(x)from(select id,name,currency,timezone,last_success_at from crm_private.meta_accounts where organization_id=org order by name,id limit 100)x),'[]'::jsonb);end$$;
revoke all on function public.crm_meta_spend(text,jsonb,text,integer),public.crm_meta_report_accounts()from public,anon,authenticated,service_role;
grant execute on function public.crm_meta_spend(text,jsonb,text,integer),public.crm_meta_report_accounts()to authenticated;
commit;
